using System.Data;
using System.Security.Claims;
using System.Text.Json;
using Npgsql;
record HospitalContext(string HospitalId,string UserId,string? PatientId);
record HospitalEntry(string Id,string Name,string Address,string City,string State,string PostalCode,bool Active,bool AcceptingReferrals,bool IsDemo);
record NetworkProvider(string Id,string HospitalId,string RegistrationId,string Name,string Department,string Start,string End);
record ReferralEntry(string Id,string PatientId,string PatientName,string PatientCode,string SourceHospitalId,string TargetHospitalId,string? TargetDoctorId,string Reason,string Status,DateTimeOffset CreatedAt,string? ResolutionNote);
sealed partial class Store {
    static readonly AsyncLocal<HospitalContext?> hospitalContext=new();
    public static HospitalContext? ContextHospital=>hospitalContext.Value;
    public static void SetHospitalContext(HospitalContext? value)=>hospitalContext.Value=value;
    public async Task<bool> UserHasOtherHospitals(string id){await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM hospitalflow.hospital_memberships WHERE user_id=$1 AND hospital_id<>hf_security.current_hospital() AND active)",c);cmd.Parameters.AddWithValue(id);return (bool)(await cmd.ExecuteScalarAsync())!;}
    public async Task<bool> UserInHospital(string id){await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM hospitalflow.hospital_memberships WHERE user_id=$1 AND hospital_id=hf_security.current_hospital() AND active)",c);cmd.Parameters.AddWithValue(id);return (bool)(await cmd.ExecuteScalarAsync())!;}
    public async Task<bool> NetworkOperator(string id){await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM hospitalflow.network_operators WHERE user_id=$1 UNION ALL SELECT 1 FROM hospitalflow.users WHERE id=$1 AND role='Developer')",c);cmd.Parameters.AddWithValue(id);return (bool)(await cmd.ExecuteScalarAsync())!;}
    public async Task<HospitalContext?> ResolveHospital(string id,string? requested){
        await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT h.id,a.patient_id FROM hospitalflow.hospitals h LEFT JOIN hospitalflow.patient_accounts a ON a.user_id=$1 WHERE h.active AND (EXISTS(SELECT 1 FROM hospitalflow.hospital_memberships m WHERE m.user_id=$1 AND m.hospital_id=h.id AND m.active) OR EXISTS(SELECT 1 FROM hospitalflow.network_operators o WHERE o.user_id=$1) OR EXISTS(SELECT 1 FROM hospitalflow.users WHERE id=$1 AND role='Developer')) AND ($2::text IS NULL OR h.id=$2) ORDER BY CASE WHEN h.id=(SELECT hospital_id FROM hospitalflow.user_preferences WHERE user_id=$1) THEN 0 ELSE 1 END,h.id LIMIT 1",c);
        cmd.Parameters.AddWithValue(id);cmd.Parameters.Add(new NpgsqlParameter{NpgsqlDbType=NpgsqlTypes.NpgsqlDbType.Text,Value=(object?)requested??DBNull.Value});await using var r=await cmd.ExecuteReaderAsync();return await r.ReadAsync()?new(r.GetString(0),id,r.IsDBNull(1)?null:r.GetString(1)):null;
    }
    public async Task<List<HospitalEntry>> Hospitals(){await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT id,name,address,city,state,postal_code,active,accepting_referrals,is_demo FROM hospitalflow.hospitals ORDER BY id",c);await using var r=await cmd.ExecuteReaderAsync();var list=new List<HospitalEntry>();while(await r.ReadAsync())list.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetBoolean(6),r.GetBoolean(7),r.GetBoolean(8)));return list;}
    public async Task<object> NetworkState(string id){
        var actorForNetwork=await UserById(id);var isNurse=actorForNetwork?.Role=="Nurse";var hospitals=await Hospitals();var access=new List<string>();var providers=new List<NetworkProvider>();var referrals=new List<ReferralEntry>();await using var c=await Open();
        await using(var cmd=new NpgsqlCommand("SELECT hospital_id FROM hospitalflow.hospital_memberships WHERE user_id=$1 AND active",c)){cmd.Parameters.AddWithValue(id);await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())access.Add(r.GetString(0));}
        if(isNurse)return new{hospitals=hospitals.Where(h=>access.Contains(h.Id)),providers,referrals,access,currentHospitalId=ContextHospital?.HospitalId,canManageNetwork=false};
        if(await NetworkOperator(id))access=hospitals.Where(h=>h.Active).Select(h=>h.Id).ToList();
        await using(var cmd=new NpgsqlCommand("SELECT id,hospital_id,registration_id,name,department,shift_start::text,shift_end::text FROM hf_security.directory_providers() ORDER BY hospital_id,name",c)){await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())providers.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5)[..5],r.GetString(6)[..5]));}
        var patient=await PatientAccount(id);var actor=await UserById(id);var canSeeReferrals=patient!=null||Access.Full(actor?.Role)||(await Permissions(id)).Any(p=>p is "Doctor" or "Nurse" or "Reception");
        // Patient identity is shared only in referrals addressed to this hospital or sent by it.
        if(canSeeReferrals)await using(var cmd=new NpgsqlCommand("SELECT r.id::text,r.patient_id,p.name,p.registration_id,r.source_hospital_id,r.target_hospital_id,r.target_doctor_id,r.reason,r.status,r.created_at,r.resolution_note FROM hospitalflow.referrals r JOIN hf_security.referral_patient_identity() p ON p.id=r.patient_id ORDER BY r.created_at DESC",c)){await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())referrals.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.GetString(7),r.GetString(8),new DateTimeOffset(r.GetDateTime(9),TimeSpan.Zero),r.IsDBNull(10)?null:r.GetString(10)));}
        return new{hospitals,providers,referrals,access,currentHospitalId=ContextHospital?.HospitalId,canManageNetwork=await NetworkOperator(id)};
    }
    public async Task SelectHospital(string hospitalId,AuditContext audit){if(await ResolveHospital(audit.ActorId!,hospitalId)==null)throw new RuleException("You do not have access to this hospital.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await Sql(c,tx,"INSERT INTO hospitalflow.user_preferences(user_id,theme,hospital_id) VALUES($1,'Default',$2) ON CONFLICT(user_id) DO UPDATE SET hospital_id=EXCLUDED.hospital_id,updated_at=now()",audit.ActorId!,hospitalId);await new RowMap<Audit>("activity_log").Save(c,tx,[audit.Event("hospital-selected",hospitalId)],[]);await tx.CommitAsync();}
    public async Task<string> ReferPatient(JsonElement body,AuditContext audit,string key){
        if(!Guid.TryParse(key,out var retry))throw new RuleException("A valid Idempotency-Key is required.");
        var patientId=ProfileText(body,"patientId",100);var target=ProfileText(body,"targetHospitalId",100);var doctor=ProfileText(body,"targetDoctorId",100,false);var reason=ProfileText(body,"reason",2000);if(reason.Length<5)throw new RuleException("Provide a referral reason of at least 5 characters.");
        if(target==ContextHospital?.HospitalId&&doctor.Length==0)throw new RuleException("Choose a receiving doctor for a referral within this hospital.");
        var hash=RequestHash(body.GetRawText());await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await Sql(c,tx,"SELECT pg_advisory_xact_lock(74192301),set_config('hospitalflow.actor_id',$1,true),set_config('hospitalflow.correlation_id',$2,true)",audit.ActorId!,audit.CorrelationId);
        await Sql(c,tx,"SELECT hf_security.require_actor(ARRAY['Doctor'])");
        await using(var old=new NpgsqlCommand("SELECT reference,request_hash FROM hospitalflow.idempotency_keys WHERE user_id=$1 AND key=$2",c,tx)){old.Parameters.AddWithValue(audit.ActorId!);old.Parameters.AddWithValue(retry);await using var r=await old.ExecuteReaderAsync();if(await r.ReadAsync()){if(r.GetString(1)!=hash)throw new RuleException("This retry key belongs to different referral details.");return r.GetString(0);}}
        await using(var validate=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM hospitalflow.patients WHERE id=$1) AND EXISTS(SELECT 1 FROM hospitalflow.hospitals WHERE id=$2 AND active AND (id=hf_security.current_hospital() OR accepting_referrals)) AND ($3='' OR EXISTS(SELECT 1 FROM hf_security.directory_providers() WHERE id=$3 AND hospital_id=$2)) AND NOT EXISTS(SELECT 1 FROM hospitalflow.person_profiles WHERE user_id=$4 AND doctor_id=$3) AND NOT EXISTS(SELECT 1 FROM hospitalflow.staff_members WHERE user_id=$4 AND doctor_id=$3 AND active)",c,tx)){validate.Parameters.AddWithValue(patientId);validate.Parameters.AddWithValue(target);validate.Parameters.AddWithValue(doctor);validate.Parameters.AddWithValue(audit.ActorId!);if(!(bool)(await validate.ExecuteScalarAsync())!)throw new RuleException("Choose a registered patient, an available destination hospital and a doctor at that hospital.");}
        var id=Guid.NewGuid().ToString();await using(var cmd=new NpgsqlCommand("INSERT INTO hospitalflow.referrals(id,patient_id,source_hospital_id,target_hospital_id,target_doctor_id,referred_by,reason) VALUES($1,$2,hf_security.current_hospital(),$3,NULLIF($4,''),$5,$6)",c,tx)){cmd.Parameters.AddWithValue(Guid.Parse(id));cmd.Parameters.AddWithValue(patientId);cmd.Parameters.AddWithValue(target);cmd.Parameters.AddWithValue(doctor);cmd.Parameters.AddWithValue(audit.ActorId!);cmd.Parameters.AddWithValue(reason);await cmd.ExecuteNonQueryAsync();}
        await Sql(c,tx,"INSERT INTO hospitalflow.idempotency_keys(user_id,key,action,request_hash,reference) VALUES($1,$2,'referral',$3,$4)",audit.ActorId!,retry,hash,id);
        await new RowMap<Audit>("activity_log").Save(c,tx,[audit.Event("patient-referred",id)],[]);await tx.CommitAsync();return id;
    }
    public async Task ResolveReferral(JsonElement body,AuditContext audit){
        var id=Guid.TryParse(ProfileText(body,"id",100),out var parsed)?parsed:throw new RuleException("Select a referral.");var status=ProfileText(body,"status",30);var note=ProfileText(body,"note",1000);
        if(status is not("Accepted" or "Declined" or "Cancelled"))throw new RuleException("Choose a referral outcome.");
        await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await Sql(c,tx,"SELECT pg_advisory_xact_lock(74192301),set_config('hospitalflow.actor_id',$1,true),set_config('hospitalflow.correlation_id',$2,true)",audit.ActorId!,audit.CorrelationId);await Sql(c,tx,"SELECT hf_security.require_actor(ARRAY['Doctor'])");
        string pid,target;await using(var cmd=new NpgsqlCommand("UPDATE hospitalflow.referrals SET status=$1,resolved_at=now(),resolved_by=$2,resolution_note=$3 WHERE id=$4 AND status='Pending' AND (($1='Cancelled' AND source_hospital_id=hf_security.current_hospital()) OR ($1 IN ('Accepted','Declined') AND target_hospital_id=hf_security.current_hospital())) RETURNING patient_id,target_hospital_id",c,tx)){cmd.Parameters.AddWithValue(status);cmd.Parameters.AddWithValue(audit.ActorId!);cmd.Parameters.AddWithValue(note);cmd.Parameters.AddWithValue(id);await using var r=await cmd.ExecuteReaderAsync();if(!await r.ReadAsync())throw new RuleException("Referral is unavailable, already resolved or belongs to another hospital.");pid=r.GetString(0);target=r.GetString(1);}
        if(status=="Accepted"){
            await Sql(c,tx,"INSERT INTO hospitalflow.patient_hospitals(patient_id,hospital_id) VALUES($1,$2) ON CONFLICT DO NOTHING",pid,target);
            await Sql(c,tx,"INSERT INTO hospitalflow.hospital_memberships(user_id,hospital_id) SELECT user_id,$2 FROM hospitalflow.patient_accounts WHERE patient_id=$1 ON CONFLICT(user_id,hospital_id) DO UPDATE SET active=true",pid,target);
        }
        await new RowMap<Audit>("activity_log").Save(c,tx,[audit.Event("referral-"+status.ToLowerInvariant(),id.ToString())],[]);await tx.CommitAsync();
    }
    public async Task SaveHospital(JsonElement body,AuditContext audit){
        var id=ProfileText(body,"id",100,false);var name=ProfileText(body,"name",150);var address=ProfileText(body,"address",500);var city=ProfileText(body,"city",100);var region=ProfileText(body,"state",100);var postal=ProfileText(body,"postalCode",6);if(!System.Text.RegularExpressions.Regex.IsMatch(postal,@"^[0-9]{6}$"))throw new RuleException("Enter a six-digit postal code.");
        var accepting=body.TryGetProperty("acceptingReferrals",out var flag)&&flag.ValueKind==JsonValueKind.True;if(id.Length==0)id="H-"+Guid.NewGuid().ToString("N")[..12];
        await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await Sql(c,tx,"SELECT set_config('hospitalflow.actor_id',$1,true),set_config('hospitalflow.correlation_id',$2,true)",audit.ActorId!,audit.CorrelationId);
        await Sql(c,tx,"INSERT INTO hospitalflow.hospitals(id,name,address,city,state,postal_code,accepting_referrals) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,address=EXCLUDED.address,city=EXCLUDED.city,state=EXCLUDED.state,postal_code=EXCLUDED.postal_code,accepting_referrals=EXCLUDED.accepting_referrals",id,name,address,city,region,postal,accepting);
        await new RowMap<Audit>("activity_log").Save(c,tx,[audit.Event("hospital-saved",id)],[]);await tx.CommitAsync();
    }
    public async Task<object> NetworkAccounts(){await using var c=await Open();await using var cmd=new NpgsqlCommand("SELECT COALESCE(jsonb_agg(x),'[]'::jsonb)::text FROM(SELECT u.id,u.registration_id,u.name,u.email,u.role,COALESCE((SELECT jsonb_agg(jsonb_build_object('hospitalId',m.hospital_id,'active',m.active)) FROM hospitalflow.hospital_memberships m WHERE m.user_id=u.id),'[]'::jsonb) memberships FROM hospitalflow.users u ORDER BY u.name)x",c);return JsonSerializer.Deserialize<JsonElement>((string)(await cmd.ExecuteScalarAsync())!);}
    public async Task GrantHospital(JsonElement body,AuditContext audit){var user=ProfileText(body,"userId",100);var hospital=ProfileText(body,"hospitalId",100);var active=body.TryGetProperty("active",out var a)&&a.ValueKind==JsonValueKind.True;if(user==audit.ActorId&&!active)throw new RuleException("You cannot revoke your own hospital access.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await Sql(c,tx,"SELECT set_config('hospitalflow.actor_id',$1,true),set_config('hospitalflow.correlation_id',$2,true)",audit.ActorId!,audit.CorrelationId);await Sql(c,tx,"INSERT INTO hospitalflow.hospital_memberships(user_id,hospital_id,active) VALUES($1,$2,$3) ON CONFLICT(user_id,hospital_id) DO UPDATE SET active=EXCLUDED.active",user,hospital,active);await new RowMap<Audit>("activity_log").Save(c,tx,[audit.Event("hospital-access-updated",user+":"+hospital)],[]);await tx.CommitAsync();}
    public async Task<object> PatientHospitalHistory(string patientId,string userId,string role){
        var linked=await PatientAccount(userId);if(linked!=null&&linked.PatientId!=patientId)throw new RuleException("Patient history is unavailable.");
        if(linked==null&&!Access.Full(role)&&!(await Permissions(userId)).Any(p=>p is "Doctor" or "Nurse" or "Reception"))throw new RuleException("Patient history is restricted to authorised care staff.");
        var s=linked==null?await Current():await PatientState(userId);var p=s.Patients.FirstOrDefault(p=>p.Id==patientId)??throw new RuleException("Patient is not registered at this hospital.");
        await using var c=await Open();var events=new List<object>();
        // Query through RLS: staff see their selected hospital; patients see their own care across hospitals.
        await using var cmd=new NpgsqlCommand("SELECT hospital_id,id,'Appointment' kind,at,status FROM hospitalflow.appointments WHERE patient_id=$1 UNION ALL SELECT hospital_id,id,'Admission',at,status FROM hospitalflow.admissions WHERE patient_id=$1 UNION ALL SELECT hospital_id,id,'Invoice',created_at,'Recorded' FROM hospitalflow.bills WHERE patient_id=$1 UNION ALL SELECT hospital_id,id,'Prescription',created_at,status FROM hospitalflow.prescriptions WHERE patient_id=$1 ORDER BY 4 DESC NULLS LAST",c);cmd.Parameters.AddWithValue(patientId);await using(var r=await cmd.ExecuteReaderAsync()){while(await r.ReadAsync())events.Add(new{hospitalId=r.GetString(0),reference=r.GetString(1),kind=r.GetString(2),at=r.IsDBNull(3)?(DateTime?)null:r.GetDateTime(3),status=r.GetString(4)});}
        var referrals=new List<object>();await using(var refs=new NpgsqlCommand("SELECT id::text,source_hospital_id,target_hospital_id,status,created_at,reason FROM hospitalflow.referrals WHERE patient_id=$1 ORDER BY created_at",c)){refs.Parameters.AddWithValue(patientId);await using var r=await refs.ExecuteReaderAsync();while(await r.ReadAsync())referrals.Add(new{id=r.GetString(0),sourceHospitalId=r.GetString(1),targetHospitalId=r.GetString(2),status=r.GetString(3),at=r.GetDateTime(4),reason=r.GetString(5)});}
        var registrations=new List<object>();await using(var registrationsCmd=new NpgsqlCommand("SELECT hospital_id,registered_at FROM hospitalflow.patient_hospitals WHERE patient_id=$1 AND (hospital_id=hf_security.current_hospital() OR hf_security.own_patient(patient_id)) ORDER BY registered_at",c)){registrationsCmd.Parameters.AddWithValue(patientId);await using var r=await registrationsCmd.ExecuteReaderAsync();while(await r.ReadAsync())registrations.Add(new{hospitalId=r.GetString(0),at=r.GetDateTime(1)});}
        return new{patient=new{p.Id,p.Name,p.RegistrationId},events,referrals,registrations,scope=linked!=null?"Your records across hospitals":"Selected hospital records and authorised referral summaries"};
    }
}
static class HospitalNetworkEndpoints {
    public static void Map(WebApplication app,Store store){
        AuditContext Audit(HttpContext c)=>new(c.User.Identity!.Name!,c.User.FindFirstValue(ClaimTypes.NameIdentifier),c.TraceIdentifier,c.Connection.RemoteIpAddress?.ToString(),c.Request.Method);
        app.MapGet("/api/network/workspaces",async(HttpContext c)=>{return Results.Ok(await store.NetworkState(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!));}).RequireAuthorization();
        app.MapGet("/api/network",async(HttpContext c)=>{if(c.User.FindFirstValue(ClaimTypes.Role)=="Nurse")return Results.Forbid();return Results.Ok(await store.NetworkState(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!));}).RequireAuthorization();
        app.MapPost("/api/network/hospitals",async(JsonElement b,HttpContext c)=>{if(!await store.NetworkOperator(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Results.Forbid();await store.SaveHospital(b,Audit(c));return Results.Ok();}).RequireAuthorization();
        app.MapPost("/api/network/select",async(JsonElement b,HttpContext c)=>{await store.SelectHospital(b.GetProperty("hospitalId").GetString()!,Audit(c));return Results.Ok();}).RequireAuthorization();
        app.MapGet("/api/network/access",async(HttpContext c)=>{if(!await store.NetworkOperator(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Results.Forbid();return Results.Ok(await store.NetworkAccounts());}).RequireAuthorization();
        app.MapPost("/api/network/access",async(JsonElement b,HttpContext c)=>{if(!await store.NetworkOperator(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Results.Forbid();await store.GrantHospital(b,Audit(c));return Results.Ok();}).RequireAuthorization();
        app.MapPost("/api/network/referrals",async(JsonElement b,HttpContext c)=>{var role=c.User.FindFirstValue(ClaimTypes.Role)!;if(!Access.Full(role)&&!(await store.Permissions(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!)).Contains("Doctor"))return Results.Forbid();var id=await store.ReferPatient(b,Audit(c),c.Request.Headers["Idempotency-Key"].ToString());return Results.Ok(new{reference=id});}).RequireAuthorization();
        app.MapPost("/api/network/referrals/resolve",async(JsonElement b,HttpContext c)=>{var role=c.User.FindFirstValue(ClaimTypes.Role)!;if(!Access.Full(role)&&!(await store.Permissions(c.User.FindFirstValue(ClaimTypes.NameIdentifier)!)).Contains("Doctor"))return Results.Forbid();await store.ResolveReferral(b,Audit(c));return Results.Ok();}).RequireAuthorization();
        app.MapGet("/api/network/patients/{id}/history",async(string id,HttpContext c)=>{var result=await store.PatientHospitalHistory(id,c.User.FindFirstValue(ClaimTypes.NameIdentifier)!,c.User.FindFirstValue(ClaimTypes.Role)!);await store.Log(Audit(c).Event("patient-history-view",id));return Results.Ok(result);}).RequireAuthorization();
    }
}
